<template><div class="admin-dashboard"><section class="dashboard-welcome"><div><span>THE STUDIO, AT A GLANCE</span><h1>经营驾驶舱</h1><p>预约、收款、交付和团队表现一目了然。</p></div><el-button :loading="loading" @click="load">刷新数据</el-button></section><section class="dashboard-panel quick-panel"><div class="panel-heading"><h2>快捷入口</h2><span class="quick-caption">常用功能，一步直达</span></div><div class="quick-grid"><router-link v-for="item in shortcuts" :key="item.path" :to="item.path" class="quick-item"><el-icon class="quick-icon"><component :is="item.icon"/></el-icon><div><strong>{{item.label}}</strong><small>{{item.note}}</small></div><el-icon class="quick-arrow"><ArrowRight/></el-icon></router-link></div></section><div class="dashboard-stats dashboard-stats-enhanced"><div v-for="item in cards" :key="item.label" class="metric-card"><span>{{item.label}}</span><strong>{{item.value}}</strong><small>{{item.note}}</small></div></div><section class="dashboard-insights"><section class="dashboard-panel"><div class="panel-heading"><h2>预约趋势</h2><el-radio-group v-model="days" size="small" @change="loadTrend"><el-radio-button :label="7">7天</el-radio-button><el-radio-button :label="30">30天</el-radio-button></el-radio-group></div><p class="chart-legend">● 预约量　<span>● 已完成订单</span>　<em>● 取消量</em></p><p v-if="maxTrend===1&&!trend.some(x=>Number(x.total))" class="trend-empty">所选时段暂无新预约</p><div class="trend-bars"><div v-for="item in trend" :key="item.day" class="trend-item"><div class="bar-group" :title="`${item.day}：预约 ${item.total}，已完成 ${item.completed}，取消 ${item.cancelled}`"><span class="total" :style="{height:Math.max(0,item.total/maxTrend*100)+'%'}"></span><span class="completed" :style="{height:Math.max(0,item.completed/maxTrend*100)+'%'}"></span><span class="cancelled" :style="{height:Math.max(0,item.cancelled/maxTrend*100)+'%'}"></span></div><small>{{days===7||trend.indexOf(item)%5===0?String(item.day).slice(5):'·'}}</small></div></div></section><section class="dashboard-panel"><div class="panel-heading"><h2>摄影师表现</h2></div><el-table :data="photographers" size="small"><el-table-column prop="name" label="摄影师"/><el-table-column prop="bookings" label="预约"/><el-table-column prop="completed" label="完成"/><el-table-column prop="rating" label="评分"/><el-table-column prop="delivery" label="待交付"/><el-table-column prop="revenue" label="收款"/></el-table></section></section><section class="dashboard-panel"><div class="panel-heading"><h2>近期预约</h2><router-link class="panel-link" to="/sheyingshiyuyue">查看全部</router-link></div><el-table :data="bookings" v-loading="loading" empty-text="暂无预约记录"><el-table-column prop="sheyingxingming" label="摄影师"/><el-table-column prop="yonghuxingming" label="客户"/><el-table-column prop="yuyuesheyingriqi" label="拍摄日期"/><el-table-column prop="sfsh" label="审核状态"/></el-table></section></div></template>
<script setup>
import {ref,computed,getCurrentInstance} from 'vue'
const http=getCurrentInstance().appContext.config.globalProperties.$http,loading=ref(false),days=ref(7),summary=ref({}),trend=ref([]),photographers=ref([]),bookings=ref([])
const shortcuts=computed(()=>{
 const table=localStorage.getItem('sessionTable')||''
 let allowed=new Set()
 try{const menus=JSON.parse(localStorage.getItem('menus')||'[]');const current=menus.find(x=>x.tableName===table);allowed=new Set((current?.backMenu||[]).flatMap(x=>x.child||[]).map(x=>x.classname||x.tableName))}catch{}
 const booking=allowed.has('sheyingshiyuyue')
 return [
  {label:'在线咨询',path:'/chat',icon:'Service',note:'查看咨询，及时回复客户',show:allowed.has('chat')},
  {label:'拍摄预约',path:'/sheyingshiyuyue',icon:'Calendar',note:'确认预约与跟进订单',show:booking},
  {label:'档期日历',path:'/booking-calendar',icon:'Clock',note:'查看拍摄安排与空闲档期',show:booking},
  {label:'消息中心',path:'/message-center',icon:'Bell',note:'集中查看通知与待办',show:['users','sheyingshi'].includes(table)},
  {label:'改期与取消',path:'/booking-changes',icon:'Refresh',note:'处理客户预约变更',show:booking},
  {label:'退款管理',path:'/booking-refunds',icon:'Wallet',note:table==='users'?'审核退款与登记处理结果':'查看订单退款进度',show:booking},
  {label:'摄影作品',path:'/sheyingzuopin',icon:'Picture',note:'管理作品与拍摄展示',show:allowed.has('sheyingzuopin')},
  {label:'活动管理',path:'/huodongxinxi',icon:'Present',note:'发布活动与管理报名',show:allowed.has('huodongxinxi')}
 ].filter(x=>x.show)
})
const cards=computed(()=>[{label:'预约总量',value:summary.value.total??'—',note:'全部预约'},{label:'待审核',value:summary.value.pending??'—',note:'需要及时处理'},{label:'已支付金额',value:summary.value.paid==null?'—':'¥ '+Number(summary.value.paid).toFixed(2),note:'工作室收款'},{label:'净收款',value:summary.value.net==null?'—':'¥ '+Number(summary.value.net).toFixed(2),note:'扣除已登记退款'},{label:'改期/取消申请',value:summary.value.changeRequests??'—',note:'待处理申请'},{label:'待审核退款',value:summary.value.refundPending??'—',note:'退款管理中处理'},{label:'已登记退款',value:summary.value.refunded==null?'—':'¥ '+Number(summary.value.refunded).toFixed(2),note:'已完成退款登记'},{label:'待交付订单',value:summary.value.delivery??'—',note:'拍摄已完成'}])
const maxTrend=computed(()=>Math.max(1,...trend.value.map(x=>Number(x.total)||0)))
function fillTrend(rows){return Array.from({length:days.value},(_,i)=>{const d=new Date();d.setDate(d.getDate()-days.value+1+i);const key=`${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`;return rows.find(x=>String(x.day).slice(0,10)===key)||{day:key,total:0,completed:0,cancelled:0}})}
async function loadTrend(){const r=await http.get('stage3/dashboard/trend',{params:{days:days.value}});trend.value=fillTrend(r.data.data||[])}
async function load(){loading.value=true;try{const [s,t,p,b]=await Promise.all([http.get('stage3/dashboard/summary'),http.get('stage3/dashboard/trend',{params:{days:days.value}}),http.get('stage3/dashboard/photographers'),http.get('sheyingshiyuyue/page',{params:{page:1,limit:6,sort:'id',order:'desc'}})]);summary.value=s.data.data||{};trend.value=fillTrend(t.data.data||[]);photographers.value=p.data.data||[];bookings.value=b.data.data.list||[]}finally{loading.value=false}}
load()
</script>
<style scoped>
.quick-panel{margin-bottom:24px}.quick-caption{font-size:12px;color:var(--el-text-color-secondary)}.quick-grid{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:12px}.quick-item{display:flex;align-items:center;gap:12px;padding:16px;border:1px solid var(--el-border-color-light);border-radius:10px;min-width:0;background:var(--desk-surface,#fff);transition:background .15s,border-color .15s}.quick-item:hover,.quick-item:focus-visible{background:var(--el-color-primary-light-9);border-color:var(--el-color-primary);outline:none}.quick-icon{width:42px;height:42px;border-radius:12px;flex-shrink:0;font-size:21px;background:var(--el-color-primary-light-9);color:var(--el-color-primary)}.quick-item>div{min-width:0;flex:1}.quick-item strong{display:block;font-size:14px;font-weight:500;color:var(--el-text-color-primary)}.quick-item small{display:block;font-size:11px;color:var(--el-text-color-secondary);margin-top:6px;line-height:1.6}.quick-arrow{font-size:12px;color:var(--el-text-color-placeholder);flex-shrink:0}@media(max-width:1200px){.quick-grid{grid-template-columns:repeat(2,minmax(0,1fr))}}@media(max-width:600px){.quick-grid{grid-template-columns:1fr}.quick-caption{display:none}}
.metric-card{display:flex;flex-direction:column;gap:10px;background:var(--desk-surface,#fff);border:1px solid var(--el-border-color-light,#e8ebf0);border-radius:10px;padding:20px}.metric-card strong{font-size:28px;color:var(--el-text-color-primary,#315e4a)}.dashboard-insights{display:grid;grid-template-columns:1.2fr 1fr;gap:18px;margin-bottom:18px}.panel-heading{display:flex;align-items:center;justify-content:space-between;margin-bottom:16px}.panel-heading h2{margin:0;color:#345842;font-size:18px}.panel-link{color:#4a8f72}.trend-empty{font-size:12px;color:var(--el-text-color-secondary);text-align:center;margin:0}.trend-bars{height:180px;display:flex;align-items:flex-end;gap:10px;border-bottom:1px solid #e8eee7;padding:0 8px}.trend-item{height:100%;flex:1;display:flex;flex-direction:column;justify-content:flex-end;align-items:center;gap:7px}.trend-item span{width:100%;max-width:32px;background:linear-gradient(#66b9a1,#367256);border-radius:5px 5px 0 0}.bar-group{height:145px;display:flex;width:100%;align-items:flex-end;gap:2px}.bar-group span{min-width:2px}.bar-group .completed{background:#409eff}.bar-group .cancelled{background:#e6a23c}.chart-legend{font-size:12px;color:#367256}.chart-legend span{color:#409eff}.chart-legend em{color:#e6a23c;font-style:normal}.trend-item small{font-size:10px;color:#94a095}@media(max-width:900px){.dashboard-insights{grid-template-columns:1fr}}</style>
